/**
 * The bundled speaking prompts, written in the language they are shown in.
 *
 * Every entry names its instruction language, so English is one language in
 * the catalogue rather than the source every other language is translated
 * from. A learner whose instruction language has no entry yet gets a prompt
 * generated by their own LLM in the Rust core, and falls
 * back to the English entries with a visible hint.
 */
export interface CataloguePrompt {
	/** Stable id, also used as the prompt row's id when it is seeded. */
	id: string;
	/** ISO 639-1 code of the instruction language the text is written in. */
	instructionLanguage: string;
	/** Short topic name, in the instruction language; it becomes a session's title. */
	title: string;
	/** The task the learner speaks about, in the instruction language. */
	text: string;
	/** Target languages it is written for; absent means any target language. */
	targetLanguages?: readonly string[];
	/** Optional grouping, e.g. `everyday`; stored on the row and unused by the UI. */
	category?: string;
}

