/** Every bundled prompt. Add entries here; the rest of the app reads them through the helpers below. */
export const PROMPT_CATALOGUE: readonly CataloguePrompt[] = [
	...ENGLISH_GENERAL_PROMPTS,
	...RUSSIAN_GENERAL_PROMPTS,
	...ENGLISH_TARGET_PROMPTS
];

/**
 * The catalogue prompts that suit a pair of languages.
 *
 * @param instructionLanguageId The language the text is written in.
 * @param targetLanguageId The language being studied.
 * @returns The matching entries, in catalogue order; empty when that
 *   instruction language has no entries yet.
 */
export function cataloguePromptsFor(
	instructionLanguageId: string,
	targetLanguageId: string
): CataloguePrompt[] {
	return PROMPT_CATALOGUE.filter((prompt) => {
		if (prompt.instructionLanguage !== instructionLanguageId) return false;
		return !prompt.targetLanguages || prompt.targetLanguages.includes(targetLanguageId);
	});
}

/**
 * The English text of a bundled prompt by its title. Sessions recorded before
 * prompts stored their instruction language keep only the title, so this is
 * how their prompt is shown again after a restore.
 *
 * @param title The session's title, which was the prompt's title.
 * @returns The prompt text, or null when no English entry has that title.
 */
export function englishPromptTextByTitle(title: string): string | null {
	const match = PROMPT_CATALOGUE.find(
		(prompt) => prompt.instructionLanguage === 'en' && prompt.title === title
	);
	return match?.text ?? null;
}
